Queue<Integer> queue = new ArrayDeque<>();
queue.offer(1);
queue.offer(2);
queue.offer(3);

System.out.println(queue.poll() + " " + queue.peek() + " " + queue.size());

PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
pq.offer(10);
pq.offer(30);
pq.offer(20);
pq.offer(40);
pq.offer(50);

System.out.println(pq.poll() + " " + pq.poll() + " " + pq.peek());

Deque<Integer> dq = new ArrayDeque<>();
dq.push(1);
dq.push(2);
dq.push(3);
dq.offerLast(4);

int top = dq.pop();
System.out.println(top + " " + dq.peekLast() + " " + dq);

